import sys
import os
import pickle
import subprocess

def parse_project_file(project_file):
    tasks = []
    with open(project_file, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line:
                parts = line.split(':', 1)
                if len(parts) == 2:
                    task_name, command_text = parts
                    tasks.append((task_name, command_text))
    return tasks

def run_command(command_text):
    try:
        result = subprocess.run(command_text, shell=True, check=True, text=True, capture_output=True)
        return result.returncode
    except subprocess.CalledProcessError as e:
        return e.returncode

def load_cache():
    cache_file = 'task_cache.bin'
    if os.path.exists(cache_file):
        with open(cache_file, 'rb') as f:
            return pickle.load(f)
    return {}

def save_cache(cache):
    cache_file = 'task_cache.bin'
    with open(cache_file, 'wb') as f:
        pickle.dump(cache, f)

def main():
    if len(sys.argv) != 2:
        print("Usage: python taskrunner.py PROJECT_FILE", file=sys.stderr)
        sys.exit(1)

    project_file = sys.argv[1]
    tasks = parse_project_file(project_file)
    cache = load_cache()

    for task_name, command_text in tasks:
        exit_code = run_command(command_text)
        previous_exit = cache.get(task_name, None)
        print(f"{task_name} EXIT={exit_code} PREV={previous_exit if previous_exit is not None else 'none'}")
        cache[task_name] = exit_code

    save_cache(cache)

if __name__ == "__main__":
    main()

