import argparse
import json
import os
import random
import string
import sys
from datetime import datetime

TOKEN_STORE_FILE = "token_store.json"

def generate_token():
    chars = string.ascii_letters + string.digits + string.punctuation.replace('"', '').replace("'", '')
    return ''.join(random.choice(chars) for _ in range(32))

def load_token_store():
    if not os.path.exists(TOKEN_STORE_FILE):
        return []
    with open(TOKEN_STORE_FILE, 'r') as f:
        return json.load(f)

def save_token_store(tokens):
    with open(TOKEN_STORE_FILE, 'w') as f:
        json.dump(tokens, f, indent=2)

def issue_token(user_id):
    tokens = load_token_store()
    token = generate_token()
    while token in [t['token'] for t in tokens]:
        token = generate_token()

    new_token = {
        'token': token,
        'user_id': user_id,
        'created_at': datetime.now().isoformat(),
        'revoked': False
    }
    tokens.append(new_token)
    save_token_store(tokens)
    print(token)

def validate_token(token):
    tokens = load_token_store()
    for t in tokens:
        if t['token'] == token and not t['revoked']:
            print(f"VALID {t['user_id']}")
            return
    print("INVALID")

def revoke_token(token):
    tokens = load_token_store()
    for t in tokens:
        if t['token'] == token:
            t['revoked'] = True
            save_token_store(tokens)
            print("REVOKED")
            return
    print("NOT_FOUND")

def list_tokens():
    tokens = load_token_store()
    tokens.sort(key=lambda x: x['created_at'])
    for t in tokens:
        status = "revoked" if t['revoked'] else "active"
        print(f"{t['token']} {t['user_id']} {t['created_at']} {status}")

def main():
    parser = argparse.ArgumentParser(description='Manage personal access tokens.')
    subparsers = parser.add_subparsers(dest='command', required=True)

    issue_parser = subparsers.add_parser('issue', help='Issue a new token for a user')
    issue_parser.add_argument('user_id', type=str, help='User ID to associate with the token')

    validate_parser = subparsers.add_parser('validate', help='Validate a token')
    validate_parser.add_argument('token', type=str, help='Token to validate')

    revoke_parser = subparsers.add_parser('revoke', help='Revoke a token')
    revoke_parser.add_argument('token', type=str, help='Token to revoke')

    list_parser = subparsers.add_parser('list', help='List all tokens')

    args = parser.parse_args()

    if args.command == 'issue':
        issue_token(args.user_id)
    elif args.command == 'validate':
        validate_token(args.token)
    elif args.command == 'revoke':
        revoke_token(args.token)
    elif args.command == 'list':
        list_tokens()

if __name__ == "__main__":
    main()

