import sys
import xml.etree.ElementTree as ET
from collections import defaultdict

def parse_overrides(overrides_file):
    overrides = {}
    with open(overrides_file, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if '=' in line:
                name, value = line.split('=', 1)
                overrides[name.strip()] = value.strip()
    return overrides

def merge_options(base_config, overrides):
    root = ET.fromstring(base_config)
    options = defaultdict(str)

    # Parse existing options
    for option in root.findall('option'):
        options[option.attrib['name']] = option.text

    # Apply overrides
    for name, value in overrides.items():
        if name in options:
            option = root.find(f'option[@name="{name}"]')
            if option is not None:
                option.text = value
        else:
            new_option = ET.Element('option', name=name)
            new_option.text = value
            root.append(new_option)

    return ET.tostring(root, encoding='unicode')

def main():
    if len(sys.argv) != 3:
        print("Usage: apply_options_overrides.py BASE_CONFIG.xml OVERRIDES.txt")
        sys.exit(1)

    base_config = sys.argv[1]
    overrides_file = sys.argv[2]

    try:
        overrides = parse_overrides(overrides_file)
        with open(base_config, 'r') as f:
            base_xml = f.read()
        result = merge_options(base_xml, overrides)
        print(result)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

