import sys
import json
import xml.etree.ElementTree as ET

def parse_xml_file(file_path):
    tree = ET.parse(file_path)
    root = tree.getroot()
    config_dict = {}
    for entry in root.findall('entry'):
        name = entry.get('name')
        value = entry.get('value')
        if name and value:
            config_dict[name] = value
    return config_dict

def main():
    if len(sys.argv) < 2:
        print("Usage: python config_resolver.py path/to/config.xml key1=value1 key2=value2 ...")
        sys.exit(1)

    xml_path = sys.argv[1]
    config_dict = parse_xml_file(xml_path)

    for arg in sys.argv[2:]:
        if '=' in arg:
            name, value = arg.split('=', 1)
            config_dict[name] = value

    print(json.dumps(config_dict))

if __name__ == "__main__":
    main()

