import json
import sys
import re

def render_template(template_path, data_path):
    with open(template_path, 'r') as template_file:
        template = template_file.read()

    with open(data_path, 'r') as data_file:
        data = json.load(data_file)

    # Create a context with the JSON data
    context = data.copy()

    # Process simple {{key}} tags
    def replace_simple(match):
        key = match.group(1)
        if key in context:
            return str(context[key])
        return ""

    template = re.sub(r'\{\{([a-zA-Z0-9_]+)\}\}', replace_simple, template)

    # Process {{= expression}} tags
    def evaluate_expression(match):
        expr = match.group(1)
        try:
            # Evaluate the expression in the context
            result = eval(expr, {'__builtins__': None}, context)
            return str(result)
        except:
            return ""

    template = re.sub(r'\{\{=(.*?)\}\}', evaluate_expression, template)

    print(template)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python render_page.py <template.html> <data.json>")
        sys.exit(1)

    render_template(sys.argv[1], sys.argv[2])

