import sys
import json
import re

def render_template(template, context):
    # Function to replace {{key}} and {{= expression}} in the template
    def replace(match):
        if match.group(1) is not None:
            # Handle {{key}}
            key = match.group(1)
            return str(context.get(key, ''))
        elif match.group(2) is not None:
            # Handle {{= expression}}
            expression = match.group(2)
            try:
                # Evaluate the expression in the context of the provided variables
                return str(eval(expression, {}, context))
            except Exception:
                return ''  # In case of any error, return empty string

    # Regular expression to match {{key}} and {{= expression}}
    pattern = re.compile(r'\{\{(\w+)\}\}|\{\{=(.*?)\}\}')  
    return pattern.sub(replace, template)

def main():
    if len(sys.argv) != 3:
        print("Usage: python render_page.py <template_file> <data_file>")
        sys.exit(1)

    template_file = sys.argv[1]
    data_file = sys.argv[2]

    # Load the JSON data
    with open(data_file, 'r') as f:
        context = json.load(f)

    # Load the HTML template
    with open(template_file, 'r') as f:
        template = f.read()

    # Render the template with the context
    rendered = render_template(template, context)

    # Output the rendered HTML
    print(rendered)

if __name__ == '__main__':
    main()

