import os
import sys
import subprocess
import xml.etree.ElementTree as ET

def parse_xml():
    try:
        tree = ET.parse('commands.xml')
        root = tree.getroot()
        commands = {}
        for cmd_elem in root.findall('command'):
            name = cmd_elem.get('name')
            role = cmd_elem.get('role')
            exec_cmd = cmd_elem.find('exec').text
            commands[name] = (role, exec_cmd)
        return commands
    except (ET.ParseError, FileNotFoundError) as e:
        print(f"Error parsing commands.xml: {e}", file=sys.stderr)
        sys.exit(1)

def get_user_role():
    if 'APP_TOKEN' not in os.environ or 'AUTH_HELPER' not in os.environ:
        print("Invalid or missing token", file=sys.stderr)
        sys.exit(1)

    token = os.environ['APP_TOKEN']
    helper_path = os.environ['AUTH_HELPER']

    try:
        process = subprocess.Popen(
            [helper_path],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate(input=token)
        if process.returncode != 0 or not stdout.strip():
            print("Invalid or missing token", file=sys.stderr)
            sys.exit(1)
        return stdout.strip()
    except Exception:
        print("Invalid or missing token", file=sys.stderr)
        sys.exit(1)

def main():
    commands = parse_xml()
    command_name = sys.argv[1] if len(sys.argv) > 1 else None

    if not command_name:
        print("No command provided", file=sys.stderr)
        sys.exit(1)

    if command_name not in commands:
        print(f"Unknown command: {command_name}", file=sys.stderr)
        sys.exit(1)

    required_role, exec_cmd = commands[command_name]
    user_role = get_user_role()

    if user_role == 'none' or user_role != required_role:
        print(f"Access denied for role {user_role}", file=sys.stderr)
        sys.exit(1)

    try:
        process = subprocess.Popen(
            exec_cmd.split(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate()
        print(stdout, end='')
        if stderr:
            print(stderr, file=sys.stderr)
        sys.exit(process.returncode)
    except Exception:
        print(f"Failed to execute command: {exec_cmd}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

