        elif child.tag == 'report':
            name = child.attrib.get('name')
            max_per_minute = int(child.attrib.get('max_per_minute'))
            sql_template = child.find('sql').text
            reports[name] = {'max_per_minute': max_per_minute, 'sql_template': sql_template}

    if not db_path:
        print("Missing database path in XML", file=sys.stderr)
        sys.exit(1)

    return db_path, reports

def generate_dates(start_date_str, end_date_str):
    start_date = datetime.strptime(start_date_str, "%Y-%m-%d").date()
    end_date = datetime.strptime(end_date_str, "%Y-%m-%d").date()
    return [start_date + timedelta(days=i) for i in range((end_date - start_date).days + 1)]

def execute_query(conn, sql_template, date_str):
    sql = sql_template.replace('{date}', date_str)
    cursor = conn.cursor()
    cursor.execute(sql)
    return cursor.fetchall()

