    report_name = sys.argv[2]
    start_date_str = sys.argv[3]
    end_date_str = sys.argv[4]

    db_path, reports = parse_xml(config_path)

    if report_name not in reports:
        print(f"Report '{report_name}' not found in configuration", file=sys.stderr)
        sys.exit(1)

    report_config = reports[report_name]
    max_per_minute = report_config['max_per_minute']
    sql_template = report_config['sql_template']

    conn = sqlite3.connect(db_path)
    try:
        dates = generate_dates(start_date_str, end_date_str)
        delay = 60.0 / max_per_minute

        for date in dates:
