from xml.etree import ElementTree as ET

def parse_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    calculations = []
    for calc in root.findall('calculation'):
        name = calc.get('name')
        expr = calc.get('expr')
        if name is None or expr is None:
            raise ValueError(f"Missing required attributes in calculation: {name}")
        calculations.append({'name': name, 'expr': expr})
    return calculations

def evaluate_expressions(vars_dict, calculations):
    results = {}
    for calc in calculations:
        try:
            result = eval(calc['expr'], {}, vars_dict)
            results[calc['name']] = result
        except Exception as e:
            raise ValueError(f"Error evaluating expression '{calc['expr']}': {str(e)}")
    return results

def serialize_cache(cache_data):
    return json.dumps(cache_data)

def deserialize_cache(cache_path):
    with open(cache_path, 'r') as f:
        return json.load(f)

def run_mode(config_path):
    calculations = parse_config(config_path)
    input_data = json.loads(sys.stdin.read())
    if not isinstance(input_data, dict):
        raise ValueError("Input must be a JSON object mapping variable names to values")

    results = evaluate_expressions(input_data, calculations)
    output = json.dumps(results)
    sys.stdout.write(output + '\n')

    cache_data = {
        'calculations': calculations,
        'input_vars': input_data,
        'results': results
    }
    cache_path = 'calcflow.cache'
    with open(cache_path, 'w') as f:
