        return int(os.environ['N_VALUE'])
    return 1

def load_cache():
    if os.path.exists('.job_cache.bin'):
        with open('.job_cache.bin', 'rb') as f:
            return pickle.load(f)
    return {}

def save_cache(cache):
    with open('.job_cache.bin', 'wb') as f:
        pickle.dump(cache, f)

def evaluate_expression(expr, n):
    try:
        # Parse the expression safely
        parsed = ast.parse(expr, mode='eval')
        # Create a safe evaluation context
        safe_namespace = {'n': n}
        # Evaluate the parsed expression
        result = eval(ast.unparse(parsed), safe_namespace)
        return result
    except Exception:
        return None

def process_job(job, n, cache, used_cost, memory_budget):
    job_id = job['id']
    cost = job['cost']

    if used_cost + cost > memory_budget:
        print(f"SKIPPED {job_id}")
        return used_cost

    if job_id in cache:
        print(f"RESULT {job_id} {cache[job_id]}")
        return used_cost + cost
    else:
        expr = job['expr']
        result = evaluate_expression(expr, n)
        if result is not None:
            cache[job_id] = result
            print(f"RESULT {job_id} {result}")
        return used_cost + cost

def main():
    if len(sys.argv) != 2:
        print("Usage: python job_runner.py path/to/config.json")
