import hashlib

def compute_digest(secret_key, token):
    combined = f"{secret_key}{token}".encode('utf-8')
    return hashlib.sha256(combined).hexdigest()

def parse_xml(config_path):
    tree = ET.parse(config_path)
    root = tree.getroot()
    secret = None
    users = []
    for child in root:
        if child.tag == 'secret':
            secret = child.attrib.get('key')
        elif child.tag == 'user':
            users.append({
                'name': child.attrib.get('name'),
                'tokenDigest': child.attrib.get('tokenDigest'),
                'roles': [role.strip() for role in child.attrib.get('roles', '').split(',')]
            })
    return secret, users

def check_roles(action, roles):
    role_to_actions = {
        'reader': {'read'},
        'writer': {'read', 'write'},
        'admin': {'read', 'write', 'delete'}
    }
    for role in roles:
        if action in role_to_actions.get(role, set()):
            return True
    return False

def main():
    if len(sys.argv) != 4:
        print("Usage: python auth_check.py CONFIG_PATH USERNAME ACTION")
        sys.exit(1)

