        self.per_user_max = int(limits.get('per_user_max'))
        self.variables = {var.get('name'): float(var.get('value')) for var in root.find('variables')}

    def evaluate_expression(self, user_id, expression):
        if self.user_success_count.get(user_id, 0) >= self.per_user_max:
            print(f'THROTTLED {user_id}')
            return
        try:
            result = eval(expression, {}, self.variables)
            self.user_success_count[user_id] = self.user_success_count.get(user_id, 0) + 1
            print(f'{user_id}: {result}')
        except Exception:
            print(f'ERROR {user_id}')

def main():
    if len(sys.argv) != 2:
        print('Usage: python script.py <config_file>')
        return
    config_file = sys.argv[1]
    evaluator = Evaluator(config_file)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        user_id, expression = line.split(': ', 1)
        evaluator.evaluate_expression(user_id, expression)

if __name__ == '__main__':
    main()
